/* From Uiverse.io by Alien14k - Tags: input */
.__UIV_SCOPE__ .form__group {
  position: relative;
}

.__UIV_SCOPE__ .form__field {
  border: 1px solid silver !important;
  border-radius: 5px;
  box-sizing: border-box;
  color: #313a46;
  height: 40px;
  padding: 0rem 15px;
}

.__UIV_SCOPE__ .form__field::placeholder {
  color: transparent;
}

.__UIV_SCOPE__ .form__field:placeholder-shown ~ .form__label {
  top: 10px;
  border-right: none;
  border-left: none;
}

.__UIV_SCOPE__ .form__label {
  background-color: white;
  border-left: 1px solid silver;
  border-right: 1px solid silver;
  color: #9b9b9b;
  display: block;
  font-size: .9em;
  margin-left: 10px;
  padding: 0 10px;
  pointer-events: none;
  position: absolute;
  top: -10px;
  transition: 0.2s;
}

.__UIV_SCOPE__ .form__field:focus {
  border: 1px solid #B9192C !important;
  outline: none;
}

.__UIV_SCOPE__ .form__field:focus ~ .form__label {
  background-color: white;
  border-right: 1px solid #B9192C;
  border-left: 1px solid #B9192C;
  color: #B9192C;
  font-size: .9em;
  margin-left: 10px;
  padding: 0 10px;
  position: absolute;
  top: -10px;
  transition: 0.2s;
}
